import { useTranslation } from 'react-i18next'
import { useNavigate } from 'react-router-dom'
import { useTenant } from '@/app/providers/TenantProvider'
import { getAppsForLevel } from '@/app/config/appRegistry'
import { useWorkspaceStore } from '@/app/store/workspaceStore'
import { Badge } from '@/shared/ui/Badge'
import * as Icons from 'lucide-react'
import type { LucideIcon } from 'lucide-react'

function DynamicIcon({ name }: { name: string }) {
  const Icon = (Icons as unknown as Record<string, LucideIcon>)[name]
  if (!Icon) return <Icons.Box size={16} />
  return <Icon size={16} />
}

export function AppsPanel() {
  const { t } = useTranslation('shell')
  const { manifest } = useTenant()
  const { projectId } = useWorkspaceStore()
  const navigate = useNavigate()

  const enabledApps = manifest?.enabledApps ?? []
  const featureFlags = manifest?.featureFlags ?? []

  const ecosystemApps = getAppsForLevel('ecosystem', enabledApps, featureFlags)
  const projectApps = projectId ? getAppsForLevel('project', manifest?.enabledProjectApps ?? [], featureFlags) : []

  const handleAppClick = (route: string) => {
    if (route.includes(':projectId') && projectId) {
      navigate(route.replace(':projectId', projectId))
    } else if (!route.includes(':')) {
      navigate(route)
    }
  }

  return (
    <div className="flex flex-col gap-1 p-3 overflow-y-auto h-full">
      <p className="text-xs text-muted-foreground font-medium uppercase tracking-wide px-1 mb-1">
        {t('apps')}
      </p>
      {ecosystemApps.map((app) => (
        <button
          key={app.id}
          onClick={() => handleAppClick(app.route)}
          className="flex items-center gap-2.5 rounded-lg px-2 py-2 text-sm hover:bg-muted transition-colors text-left w-full"
        >
          <span className="text-accent flex-shrink-0">
            <DynamicIcon name={app.icon} />
          </span>
          <span className="flex-1 truncate">{app.label}</span>
          {app.premium && <Badge variant="outline" className="text-xs">Pro</Badge>}
        </button>
      ))}

      {projectApps.length > 0 && (
        <>
          <p className="text-xs text-muted-foreground font-medium uppercase tracking-wide px-1 mt-3 mb-1">
            Project apps
          </p>
          {projectApps.map((app) => (
            <button
              key={app.id}
              onClick={() => handleAppClick(app.route)}
              className="flex items-center gap-2.5 rounded-lg px-2 py-2 text-sm hover:bg-muted transition-colors text-left w-full"
            >
              <span className="text-accent flex-shrink-0">
                <DynamicIcon name={app.icon} />
              </span>
              <span className="flex-1 truncate">{app.label}</span>
            </button>
          ))}
        </>
      )}

      {ecosystemApps.length === 0 && (
        <p className="text-sm text-muted-foreground px-2">{t('noApps')}</p>
      )}

      <div className="mt-auto pt-3 border-t border-border">
        <button
          onClick={() => navigate('/app/profile')}
          className="flex items-center gap-2.5 rounded-lg px-2 py-2 text-sm hover:bg-muted transition-colors text-left w-full"
        >
          <span className="text-accent flex-shrink-0">
            <Icons.User size={16} />
          </span>
          <span className="flex-1 truncate">Profile</span>
        </button>
      </div>
    </div>
  )
}
